use super::*;
fn observe<T>(action:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(action)}
fn extent(v:&DslValue)->usize{match v{DslValue::String(s)=>s.capacity(),DslValue::Bytes(v)=>v.capacity(),DslValue::Array(v)=>v.capacity()*size_of::<DslValue>()+v.iter().map(extent).sum::<usize>(),DslValue::Object(v)=>v.capacity()*size_of::<(String,DslValue)>()+v.iter().map(|(k,v)|k.capacity()+extent(v)).sum::<usize>(),_=>0}}
fn pointers(p:&RetainedHistoryOriginPartial)->[usize;12]{let mut result=[0;12];for(index,value)in p.cells.iter().enumerate(){result[index]=match value{Some(DslValue::String(v))=>v.as_ptr()as usize,Some(DslValue::Array(v))=>v.as_ptr()as usize,Some(DslValue::Object(v))=>v.as_ptr()as usize,_=>0}}result[10]=p.key.as_ref().map_or(0,|v|v.as_ptr()as usize);result[11]=p.retiring.as_ref().map_or(0,|v|v.as_ref()as*const dyn ErasedSnapshotRetirement as*const()as usize);result}
fn receipt(owner:&mut RetainedHistoryOriginProjection,g:RetainedCloneGrant,born:usize,released:usize)->usize{let(received,p)=owner.take_receipt().unwrap();assert_eq!(received,g);assert!(p.fits(g));assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));p.copied_bytes}
fn close_partial(p:&mut RetainedHistoryOriginPartial,g:RetainedCloneGrant)->(usize,usize){let(mut births,mut releases)=(0,0);for _ in 0..10000{if p.terminal_is_empty(){return(births,releases)}let d=p.close_demands(g.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}].into_iter().enumerate(){if axis==2&&d.capacity_bytes==0||axis==3&&d.release_bytes==0{continue}let original=pointers(p);let(result,born,released)=observe(||p.close_step(denied).unwrap());assert_eq!(result,Default::default());assert_eq!((born,released),(0,0));assert_eq!(pointers(p),original)}let(progress,born,released)=observe(||p.close_step(g).unwrap());assert!(progress.fits(g));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));births+=born;releases+=released}panic!("original origin partial close did not terminate")}
fn close_text(text:String,g:RetainedCloneGrant)->(usize,usize){let mut partial=RetainedHistoryOriginPartial::empty(DslValue::String(text));close_partial(&mut partial,g)}
#[test]
fn original_history_origin_native_projection_preserves_original_payloads_and_paid_discarded_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|k:&str|p[k].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for row in law["origins"].as_array().unwrap(){for cancel in[0,1,3,10,30,128,10000]{
  let mut original=Some(semio_framework_pack_json::from_json_str::<DslValue>(row["json"].as_str().unwrap(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap());let held=extent(original.as_ref().unwrap());let expected:serde_json::Value=serde_json::from_str(row["json"].as_str().unwrap()).unwrap();
  let original_texts=match original.as_ref().unwrap(){DslValue::Object(fields)=>{let find=|key:&str|fields.iter().find(|(k,_)|k==key).and_then(|(_,v)|if let DslValue::String(s)=v{Some(s.as_ptr()as usize)}else{None});[find("pluginId"),find("mutationId")]},_=>unreachable!()};
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(owner,born,released)=observe(||RetainedHistoryOriginProjection::admit_original(&mut original,denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0));assert_eq!(extent(original.as_ref().unwrap()),held)}
  let(owner,born,released)=observe(||RetainedHistoryOriginProjection::admit_original(&mut original,g).unwrap());assert_eq!((born,released),(0,0));let mut owner=owner.unwrap();assert_eq!(receipt(&mut owner,g,born,released),0);let(mut births,mut releases,mut copied)=(0,0,0);
  for _ in 0..cancel{if owner.is_ready(){break}let d=owner.demands(g.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}].into_iter().enumerate(){if axis==2&&d.capacity_bytes==0||axis==3&&d.release_bytes==0||axis==4&&d.copy_bytes==0{continue}let before=pointers(owner.partial.as_ref().unwrap());let(result,born,released)=observe(||owner.step(denied).unwrap());assert!(!result);assert_eq!((born,released),(0,0));assert_eq!(pointers(owner.partial.as_ref().unwrap()),before);assert!(owner.receipt().is_none())}
   let(result,born,released)=observe(||owner.step(g).unwrap());assert!(result,"original independent policy must progress");births+=born;releases+=released;copied+=receipt(&mut owner,g,born,released);
  }
  if cancel==10000{assert!(owner.is_ready());let mut output=None;let(moved,born,released)=observe(||owner.take_ready_into(&mut output,g).unwrap());assert!(moved);assert_eq!(receipt(&mut owner,g,born,released),0);
   match output.take().unwrap(){MutationOrigin::Owner=>{assert_eq!(expected["kind"],"owner");assert_eq!(copied,0)},MutationOrigin::Contributed{plugin_id,mutation_id,payload_hash}=>{assert_eq!(plugin_id.as_ptr()as usize,original_texts[0].unwrap());assert_eq!(mutation_id.0.as_ptr()as usize,original_texts[1].unwrap());assert_eq!(plugin_id,expected["pluginId"].as_str().unwrap());assert_eq!(mutation_id.0,expected["mutationId"].as_str().unwrap());assert_eq!(payload_hash.0.to_vec(),serde_json::from_value::<Vec<u8>>(expected["payloadHash"].clone()).unwrap());assert_eq!(copied,32);for text in[plugin_id,mutation_id.0]{let(b,r)=close_text(text,g);births+=b;releases+=r}},MutationOrigin::Transaction{initiator}=>{assert_eq!(initiator.artifact_id,expected["initiator"]["artifactId"].as_str().unwrap());assert_eq!(initiator.artifact_kind,expected["initiator"]["artifactKind"].as_str().unwrap());assert_eq!(copied,0);for text in[Some(initiator.artifact_id),Some(initiator.artifact_kind),initiator.dialect].into_iter().flatten(){let(b,r)=close_text(text,g);births+=b;releases+=r}}}
  }else{owner.cancel();let mut partial=None;let(moved,born,released)=observe(||owner.take_partial_into(&mut partial,g).unwrap());assert!(moved);assert_eq!(receipt(&mut owner,g,born,released),0);let(b,r)=close_partial(partial.as_mut().unwrap(),g);births+=b;releases+=r;let(_,born,released)=observe(||drop(partial));assert_eq!((born,released),(0,0))}
  let(closed,born,released)=observe(||owner.close_step(g).unwrap());assert!(closed);assert_eq!(receipt(&mut owner,g,born,released),0);assert!(owner.terminal_is_empty());assert_eq!(held+births,releases);let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));
 }}
 for row in law["invalid"].as_array().unwrap(){let mut original=Some(semio_framework_pack_json::from_json_str::<DslValue>(row.as_str().unwrap(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap());let held=extent(original.as_ref().unwrap());let mut owner=RetainedHistoryOriginProjection::admit_original(&mut original,g).unwrap().unwrap();owner.take_receipt();let(mut births,mut releases)=(0,0);let mut invalid=false;for _ in 0..10000{let(result,born,released)=observe(||owner.step(g));births+=born;releases+=released;if result.is_err(){assert!(owner.receipt().is_none());invalid=true;break}receipt(&mut owner,g,born,released);}assert!(invalid);owner.cancel();let mut partial=None;owner.take_partial_into(&mut partial,g).unwrap();owner.take_receipt();let(b,r)=close_partial(partial.as_mut().unwrap(),g);births+=b;releases+=r;drop(partial);owner.close_step(g).unwrap();owner.take_receipt();assert!(owner.terminal_is_empty());assert_eq!(held+births,releases)}
 eprintln!("[DEBUG] Original typed origin projection moves same native Strings, writes only32 funded hash bytes, pays discarded keys/nested values/container backing with independent original grants, preserves malformed/cancelled partial recipients and exact heap conservation; metadata copy0 terminalDrop0");
}

